from s114_course_common import teach,ROOT
S='astigmatism-rx'
teach(S,'l1',[
(0,'同一盞燈，兩個方向沒有一起對好焦','這是同一眼、同一束光，不是左右眼各有一條線。',[('主子午線','規則散光最強、最弱的兩個收光方向，互相垂直'),('水平方向先收好','左右壓窄，上下仍散開，所以形成直線│'),('垂直方向先收好','上下壓窄，左右仍散開，所以形成橫線─')],'橄欖球只是幫忙想曲率不同；不是整顆眼球一定長成橄欖球。'),
(2,'兩個矯正力量相差多少，就是柱鏡量','先分方向，再分D和°。',[('−3與−5 D','兩個方向需要的矯正鏡片力量'),('相差2 D','柱鏡用來補兩方向之差'),('柱鏡軸','這個方向不額外加柱鏡力量；垂直它才有完整C')],'角膜與眼內散光的合成還要保留方向，不是永遠把大小相加。'),
(4,'在焦線前後移一張接光紙','焦線之間有個圓形光斑，但仍是模糊影像。',[('散光間距','兩條焦線之間的區段，Interval of Sturm'),('COLC','circle of least confusion，最小錯亂圓；折衷的圓形光斑'),('中點怎麼算','在屈光度上取兩方向平均，不是兩個距離直接平均')],'球鏡可把光斑整體移到網膜附近；要真正合併兩焦線，還需要柱鏡補方向差。')],extras={0:[dict(type='interactive',title='同一束光，在前方、中間、後方接起來',body=['接光面移動時，看同一個亮點的光斑如何由直線變圓，再變橫線。這是放大的光學模型，不是眼內器官。'],task='依序點前方、中間、後方；中間仍是模糊圓，不是清晰小點。',height=430,html=(ROOT/'tools/learn-redo/jcc_focus_positions.html').read_text(encoding='utf-8'))]})
teach(S,'l2',[
(0,'規則，是能用兩個固定方向描述','不規則散光不能只用「兩方向沒差90°」概括。',[('規則散光','同一光學區域可用互相垂直的主方向和球柱鏡描述'),('不規則散光','不同位置曲率／方向不一致，單一球柱鏡常無法完全補償'),('GP／RGP','硬式透氣鏡片；鏡片與淚液可提供較規則前表面')],'是否適合哪種鏡片仍要評估角膜形狀與健康。'),
(2,'順規、逆規，在說哪個方向比較強','負柱鏡軸不是眼睛最強的收光方向。',[('WTR順規','眼的垂直方向較強，負柱鏡軸放近水平'),('ATR逆規','眼的水平方向較強，負柱鏡軸放近垂直'),('斜散光','主方向接近45°／135°的情況')],'先認手上的角度是角膜強方向，還是處方的柱鏡軸，再套範圍；邊界依題目分類慣例。'),
(4,'年齡改變的是族群趨勢','不是每個人到某歲就一定變成逆規。',[('年輕族群','順規較常見'),('年紀增加','逆規比例常增加'),('盛行率','某族群中有多少人符合定義，會受年齡與門檻影響')],'下頁保留講義的年齡與0.75DC門檻；不要把單一樣本比例當所有人口固定值。')])
teach(S,'l3',[
(0,'把網膜當接光屏幕，看兩焦線在哪','分類時先讓調節放鬆。',[('單純','一條剛好在網膜，另一條偏前或偏後'),('複合近視','兩條都在網膜前'),('複合遠視','兩條都在網膜後')],'「同一邊」不代表兩條在同一位置；若完全合成同一焦點，就不是這種散光模型。'),
(2,'混合型：網膜夾在兩條焦線之間','一方向需要正矯正，另一方向需要負矯正。',[('混合','一前一後；例如所需矯正+1與−2D'),('調節','同時增加兩方向收光力，移動整組焦線'),('不能消除的差','單靠調節無法把兩方向力量差變成0')],'圓形光斑不一定已在網膜上；是否能靠調節移近，要看原本的等效屈光狀態。'),
(4,'先算S和S+C，再看符號','這個算法對正散、負散寫法都成立。',[('軸方向','球鏡S'),('垂直軸方向','球鏡S加帶正負號的柱鏡C'),('怎麼分類','有0看單純；同號看複合；一正一負看混合')],'例：+3.50/−2.25×90 →90方向+3.50、180方向+1.25，兩者都正，是複合遠視型。')])
teach(S,'l4',[
(0,'球鏡給共同力量，柱鏡補方向差','沿柱鏡軸為0，是柱鏡額外作用為0，不是整片球柱鏡為0。',[('DS','diopter sphere，球面度數，各方向相同'),('DC','diopter cylinder，柱面度數，垂直軸有完整作用'),('PL','plano，球面0D；仍可能有柱鏡')],'球柱鏡的任意斜方向也有中間力量；「只一方向有度數」是主方向比較的簡寫。'),
(2,'光十字：在兩條線上各寫鏡片力量','畫的是方向與D，不是兩條焦線在眼內的位置圖。',[('兩條線','兩主子午線，互相垂直'),('負散寫法','較正的數當S，另一數減S當C'),('軸的位置','放在取作S的那條線上')],'+1@180與−2@90 →+1/−3×180；S+C仍等於−2，驗算兩方向。'),
(4,'處方符號：正負號、D、°各有工作','近視的矯正鏡片是負，不等於眼球總屈光力是負。',[('眼球總力量','一般眼是正收光系統，近遠視都不是整眼負透鏡'),('剩餘屈光誤差R','慣用近視負、遠視正'),('處方Rx','記球面、柱面與軸；課堂用0.25D步階、三位軸')],'有些講義把「收光過強／不足」另標正負；那不是R或Rx的同一符號定義。')])
teach(S,'l5',[
(0,'正負散轉換：同一鏡片換一種記法','兩個主方向力量不變，才算轉對。',[('新球面','S+C'),('新柱面','−C'),('新軸','差90°，留在1～180°')],'例：+1/−3×180與−2/+3×90，兩者在180都是+1、在90都是−2。'),
(2,'等效球鏡：用一個平均數代表兩方向','平均一樣，不代表兩副散光處方完全相同。',[('SE','spherical equivalent，S+C/2'),('−4/−2.50','−4−1.25＝−5.25D'),('保留什麼','兩主方向平均；不保留柱鏡量和軸的完整資訊')],'這個平均可用於分析或球面近似；不能拿SE直接取代完整散光矯正。'),
(4,'分類方向時先統一寫法，最不易混淆','轉負散是方便判斷的方法，不是唯一合法方法。',[('負軸近水平','順規'),('負軸近垂直','逆規'),('若是正柱鏡','先轉成負柱鏡再套；或用主方向力量直接判')],'順／逆規是方向分類；單純／複合／混合是焦點位置分類，兩組名字可同時描述同一眼。')])
teach(S,'l6',[
(0,'角膜在外，水晶體在內，都能影響散光','總散光看力量也看方向。',[('角膜','前後表面形狀影響屈光，前表面通常是主要來源'),('水晶體','本身形狀、傾斜或偏位也可貢獻'),('黃斑病變','會損害中心視覺，但不等於造成光學柱鏡散光')],'角膜K估計和全眼驗光不是同一測量，不能未比方向就直接相減。'),
(2,'兩個病名先認它長在哪裡','翼狀胬肉是表面組織長入；圓錐角膜是角膜本身變形。',[('Pterygium','常由鼻側結膜向角膜長入的翼狀組織'),('Keratoconus','kerato指角膜、conus指錐；角膜變薄、突出'),('鏡片矯正','RGP、鞏膜或混合鏡等可改善部分不規則光學')],'改善看清楚與控制疾病進展是不同目標；光配鏡不代表疾病已停止。')])
